<script setup lang="ts">
/**
 * JsonTree.Entry: one value of the tree, a leaf or a container with its entries.
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/json-tree.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { computed, ref } from 'vue'

import { Icon } from '@polymorph/vue'
import styles from '@polymorph/recipes/structure/json-tree.module.css'

export interface JsonTreeEntryProps {
  /**
   * The key or index it sits under.
   */
  name?: string
  value: unknown
  depth: number
  defaultDepth: number
}

defineOptions({ name: 'JsonTreeEntry', inheritAttrs: false })

const props = defineProps<JsonTreeEntryProps>()
const open = ref(props.depth < props.defaultDepth)
const entries = computed(() =>
  typeof props.value === 'object' && props.value !== null
    ? Array.isArray(props.value)
      ? props.value.map((item: unknown, index: number) => [String(index), item] as const)
      : Object.entries(props.value)
    : null,
)
const kind = computed(() =>
  props.value === null
    ? 'null'
    : typeof props.value === 'string'
      ? 'string'
      : typeof props.value === 'number'
        ? 'number'
        : typeof props.value === 'boolean'
          ? 'boolean'
          : 'null',
)
const spelled = computed(() =>
  kind.value === 'string' ? JSON.stringify(props.value) : String(props.value),
)
const summary = computed(() =>
  Array.isArray(props.value)
    ? `[…] ${props.value.length} ${props.value.length === 1 ? 'item' : 'items'}`
    : `{…} ${entries.value?.length ?? 0} ${entries.value?.length === 1 ? 'key' : 'keys'}`,
)
</script>

<template>
  <li v-if="entries === null" :class="styles.row">
    <!-- key -->
    <span v-if="name !== undefined" :class="styles.key">
      {{ name }}
      <span :class="styles.colon"> : </span>
    </span>
    <!-- value -->
    <span :class="styles.value" :data-kind="kind">
      {{ spelled }}
    </span>
  </li>
  <li v-else-if="entries.length === 0" :class="styles.row">
    <!-- key -->
    <span v-if="name !== undefined" :class="styles.key">
      {{ name }}
      <span :class="styles.colon"> : </span>
    </span>
    <!-- summary -->
    <span :class="styles.summary">
      {{ Array.isArray(value) ? '[]' : '{}' }}
    </span>
  </li>
  <li v-else :class="styles.row">
    <!-- toggle -->
    <button :class="styles.toggle" type="button" :aria-expanded="open" @click="open = !open">
      <!-- chevron -->
      <span :class="styles.chevron" aria-hidden="true">
        <Icon name="next" size="sm" />
      </span>
      <!-- key -->
      <span v-if="name !== undefined" :class="styles.key">
        {{ name }}
        <span :class="styles.colon"> : </span>
      </span>
      <!-- summary -->
      <span :class="styles.summary">
        {{ summary }}
      </span>
    </button>
    <!-- children -->
    <ul v-if="open" :class="styles.children">
      <template v-for="pair in entries" :key="pair[0]">
        <JsonTreeEntry
          :name="pair[0]"
          :value="pair[1]"
          :depth="depth + 1"
          :defaultDepth="defaultDepth"
        />
      </template>
    </ul>
  </li>
</template>
